  render();
  updateStatus();
}

function handleSlide(idx) {
  const cell = board[idx];

  if (selectedIdx === -1) {
    // Select own token
    if (cell === current) {
      selectedIdx = idx;
      render();
    }
    return;
  }

  // Try to move selected token to idx
  if (idx === selectedIdx) {
    // Deselect
    selectedIdx = -1;
    render();
    return;
  }

  if (cell !== EMPTY) return; // Target occupied

  if (!ADJACENT[selectedIdx].includes(idx)) return; // Not orthogonal adjacent

  // Perform move
  board[selectedIdx] = EMPTY;
  board[idx] = current;
  selectedIdx = -1;

  // Check win
  if (checkWin(current)) {
    gameOver = true;
    winner = current;
    render();
    updateStatus();
    return;
  }

  // Switch player
  current = current === X ? O : X;

  // Record position and check repetition
  recordPosition();
  if (checkRepetition()) {
    gameOver = true;
    winner = current === X ? O : X; // Player to move loses
    render();
    updateStatus();
    return;
  }

