    statusEl.style.color = '#333';
  } else if (phase === 'place') {
    const num = placed[current] + 1;
    statusEl.textContent = `${PLAYER_SYMBOL[current]} to place (${num}/4)`;
    statusEl.style.color = '#333';
  } else {
    statusEl.textContent = `${PLAYER_SYMBOL[current]} to slide`;
    statusEl.style.color = '#333';
  }
}

