  } else if (phase === 'place') {
    handlePlace(idx);
  } else {
    handleSlide(idx);
  }
}

function handlePie(idx) {
  if (board[idx] !== EMPTY) return;

  // X places first token
  board[idx] = X;
  placed[X] = 1;
  firstMoveIdx = idx;

  // Check if X already won (impossible with 1 token, but keep for completeness)
  if (checkWin(X)) {
    gameOver = true;
    winner = X;
    render();
    updateStatus();
    return;
  }

  // Now O chooses: swap or keep
  phase = 'pie_choose';
  current = O; // O makes the choice
  render();
